1	import { useState, useEffect } from "react";
2	import { Sun, Moon } from "lucide-react";
3	
4	export default function ButtonToggleTheme() {
5	  const [dark, setDark] = useState(true);
6	
7	  useEffect(() => {
8	    const saved = localStorage.getItem("theme");
9	    if (saved === "light") {
10	      setDark(false);
11	      document.documentElement.classList.remove("dark");
12	      document.documentElement.classList.add("light");
13	    }
14	  }, []);
15	
16	  function toggle() {
17	    const next = !dark;
18	    setDark(next);
19	    if (next) {
20	      document.documentElement.classList.remove("light");
21	      document.documentElement.classList.add("dark");
22	      localStorage.setItem("theme", "dark");
23	    } else {
24	      document.documentElement.classList.remove("dark");
25	      document.documentElement.classList.add("light");
26	      localStorage.setItem("theme", "light");
27	    }
28	  }
29	
30	  return (
31	    <button
32	      onClick={toggle}
33	      className="rounded-md p-1.5 transition-all hover:opacity-70"
34	      style={{ color: "var(--text-muted)" }}
35	      aria-label="Toggle theme"
36	    >
37	      {dark ? <Sun size={16} /> : <Moon size={16} />}
38	    </button>
39	  );
40	}
