1	import type { APIRoute } from "astro";
2	
3	export const prerender = false;
4	
5	export const POST: APIRoute = async ({ request }) => {
6	  try {
7	    const body = await request.json();
8	    const { name, email, message, website } = body;
9	
10	    if (website) {
11	      return new Response(JSON.stringify({ error: "Bot detected" }), { status: 400 });
12	    }
13	
14	    if (!name?.trim() || !email?.trim() || !message?.trim()) {
15	      return new Response(JSON.stringify({ error: "Todos los campos son requeridos" }), { status: 400 });
16	    }
17	
18	    if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
19	      return new Response(JSON.stringify({ error: "Email inválido" }), { status: 400 });
20	    }
21	
22	    const RESEND_API_KEY = import.meta.env.RESEND_API_KEY;
23	
24	    if (RESEND_API_KEY) {
25	      const { Resend } = await import("resend");
26	      const resend = new Resend(RESEND_API_KEY);
27	      await resend.emails.send({
28	        from: "Contacto dhardi.dev <onboarding@resend.dev>",
29	        to: "diegosamuel042@gmail.com",
30	        replyTo: email,
31	        subject: `Nuevo mensaje de ${name} — dhardi.dev`,
32	        html: `<p><strong>Nombre:</strong> ${name}</p><p><strong>Email:</strong> ${email}</p><p><strong>Mensaje:</strong></p><p>${message}</p>`,
33	      });
34	    }
35	
36	    return new Response(JSON.stringify({ ok: true }), { status: 200 });
37	  } catch {
38	    return new Response(JSON.stringify({ error: "Error interno" }), { status: 500 });
39	  }
40	};
