2	import SocialMedias from "./SocialMedias.astro";
3	import IconSend from "./icons/IconSend.astro";
4	import BlurFadeW from "./ui/BlurFadeW";
5	---
6	
7	<section id="contact" class="mx-auto max-w-5xl px-4 py-20">
8	  <h2 class="mb-2 text-sm font-semibold tracking-widest uppercase" style="color: var(--color-brand);">// Contacto</h2>
9	  <p class="mb-10 text-sm" style="color: var(--text-muted);">
10	    ¿Tienes un proyecto en mente? Hablemos.
11	  </p>
12	
13	  <BlurFadeW client:load>
14	    <div class="grid gap-10 lg:grid-cols-12">
15	      <!-- Left: Info -->
16	      <div class="lg:col-span-5">
17	        <p class="text-lg font-semibold mb-4" style="color: var(--text-primary);">
18	          Conectemos
19	        </p>
20	        <p class="text-sm mb-6" style="color: var(--text-muted);">
21	          Estoy disponible para oportunidades laborales, proyectos freelance o simplemente 
22	          para conectar con otros desarrolladores.
23	        </p>
24	        <SocialMedias />
25	      </div>
26	
27	      <!-- Right: Form -->
28	      <div class="lg:col-span-7">
29	        <form
30	          id="contact-form"
31	          class="rounded-[2rem] p-8 md:p-12"
32	          style="background: var(--bg-secondary); border: 1px solid var(--border-color); backdrop-filter: blur(16px);"
33	        >
34	          <div class="space-y-5">
35	            <div>
36	              <label for="name" class="mb-1 block text-xs font-medium" style="color: var(--text-muted);">Nombre</label>
37	              <input
38	                type="text" id="name" name="name" required
39	                class="w-full rounded-xl px-4 py-3 text-sm outline-none transition-all"
40	                style="background: var(--bg-primary); color: var(--text-primary); border: 1px solid var(--border-color);"
41	                placeholder="Tu nombre"
42	                pattern="^[a-zA-ZáéíóúÁÉÍÓÚñÑ\s]+$"
43	              />
44	              <p id="name-error" class="mt-1 text-xs hidden" style="color: var(--color-brand);"></p>
45	            </div>
46	            <div>
47	              <label for="email" class="mb-1 block text-xs font-medium" style="color: var(--text-muted);">Email</label>
48	              <input
49	                type="email" id="email" name="email" required
50	                class="w-full rounded-xl px-4 py-3 text-sm outline-none transition-all"
51	                style="background: var(--bg-primary); color: var(--text-primary); border: 1px solid var(--border-color);"
52	                placeholder="tu@email.com"
53	              />
54	              <p id="email-error" class="mt-1 text-xs hidden" style="color: var(--color-brand);"></p>
55	            </div>
56	            <div>
57	              <label for="message" class="mb-1 block text-xs font-medium" style="color: var(--text-muted);">Mensaje</label>
58	              <textarea
59	                id="message" name="message" required maxlength={500}
60	                class="w-full rounded-xl px-4 py-3 text-sm outline-none transition-all"
61	                style="background: var(--bg-primary); color: var(--text-primary); border: 1px solid var(--border-color); min-height: 120px; resize: vertical;"
62	                placeholder="Cuéntame sobre tu proyecto..."
63	              ></textarea>
64	              <p id="message-error" class="mt-1 text-xs hidden" style="color: var(--color-brand);"></p>
65	            </div>
66	            <!-- Honeypot -->
67	            <input type="text" name="website" class="hidden" tabindex="-1" autocomplete="off" />
68	            <button
69	              type="submit"
70	              class="inline-flex items-center gap-2 rounded-xl px-6 py-3 text-sm font-semibold transition-all hover:opacity-85"
71	              style="background: var(--color-brand); color: #fff;"
72	            >
73	              <IconSend size={16} /> Enviar mensaje
74	            </button>
75	            <p id="form-status" class="mt-3 text-xs hidden" style="color: var(--color-cyan);"></p>
76	          </div>
77	        </form>
78	      </div>
79	    </div>
80	  </BlurFadeW>
81	</section>
