83	<script>
84	  const form = document.getElementById('contact-form');
85	  const nameInput = document.getElementById('name');
86	  const emailInput = document.getElementById('email');
87	  const messageInput = document.getElementById('message');
88	  const nameError = document.getElementById('name-error');
89	  const emailError = document.getElementById('email-error');
90	  const messageError = document.getElementById('message-error');
91	  const formStatus = document.getElementById('form-status');
92	
93	  function validateName(v) {
94	    if (!v.trim()) return 'El nombre es requerido';
95	    if (!/^[a-zA-ZáéíóúÁÉÍÓÚñÑ\s]+$/.test(v)) return 'Solo letras y espacios';
96	    return '';
97	  }
98	  function validateEmail(v) {
99	    if (!v.trim()) return 'El email es requerido';
100	    if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(v)) return 'Email inválido';
101	    return '';
102	  }
103	  function validateMessage(v) {
104	    if (!v.trim()) return 'El mensaje es requerido';
105	    if (v.length > 500) return 'Máximo 500 caracteres';
106	    return '';
107	  }
108	
109	  function showError(el, msg) {
110	    if (msg) {
111	      el.textContent = msg;
112	      el.classList.remove('hidden');
113	      el.previousElementSibling.style.borderColor = 'var(--color-brand)';
114	    } else {
115	      el.classList.add('hidden');
116	      el.previousElementSibling.style.borderColor = 'var(--border-color)';
117	    }
118	  }
119	
120	  nameInput.addEventListener('input', () => showError(nameError, validateName(nameInput.value)));
121	  emailInput.addEventListener('input', () => showError(emailError, validateEmail(emailInput.value)));
122	  messageInput.addEventListener('input', () => showError(messageError, validateMessage(messageInput.value)));
123	
124	  form.addEventListener('submit', async (e) => {
125	    e.preventDefault();
126	    const nameErr = validateName(nameInput.value);
127	    const emailErr = validateEmail(emailInput.value);
128	    const msgErr = validateMessage(messageInput.value);
129	    showError(nameError, nameErr);
130	    showError(emailError, emailErr);
131	    showError(messageError, msgErr);
132	    if (nameErr || emailErr || msgErr) return;
133	
134	    formStatus.classList.remove('hidden');
135	    formStatus.textContent = 'Enviando...';
136	    formStatus.style.color = 'var(--text-muted)';
137	
138	    try {
139	      const res = await fetch('/api/contact', {
140	        method: 'POST',
141	        headers: { 'Content-Type': 'application/json' },
142	        body: JSON.stringify({
143	          name: nameInput.value.trim(),
144	          email: emailInput.value.trim(),
145	          message: messageInput.value.trim(),
146	        }),
147	      });
148	      if (res.ok) {
149	        formStatus.textContent = '✓ Mensaje enviado con éxito. Gracias!';
150	        formStatus.style.color = '#33c08c';
151	        form.reset();
152	      } else {
153	        const data = await res.json();
154	        formStatus.textContent = data.error || 'Error al enviar. Intenta de nuevo.';
155	        formStatus.style.color = 'var(--color-brand)';
156	      }
157	    } catch {
158	      formStatus.textContent = 'Error de conexión. Intenta de nuevo.';
159	      formStatus.style.color = 'var(--color-brand)';
160	    }
161	  });
162	</script>
